\begin{proof}
Let $z=\cos(1^\circ)+i\sin(1^\circ)$. Since $z^{360}=1$, $z$ is a root of the polynomial $X^{360}-1\in\mathbb{Q}[X]$, hence $z$ is algebraic over $\mathbb{Q}$. Its complex conjugate $\overline z=\cos(1^\circ)-i\sin(1^\circ)$ is also algebraic. Therefore
\[
\cos(1^\circ)=\frac{z+\overline z}{2}
\]
is algebraic over $\mathbb{Q}$, because the algebraic numbers form a field.\end{proof}

\begin{proof}
Set $z=\cos(1^\circ)+i\sin(1^\circ)=e^{i\pi/180}$. Then
\[
z^{360}=e^{2\pi i}=1,
\]
so $z$ is algebraic over $\mathbb{Q}$, being a root of $X^{360}-1$. Since algebraic numbers over $\mathbb{Q}$ are closed under complex conjugation, $\overline z$ is algebraic as well. Hence
\[
\cos(1^\circ)=\operatorname{Re}(z)=\frac{z+\overline z}{2}
\]
is algebraic over $\mathbb{Q}$.\end{proof}

\begin{proof}
Define $z=\cos(1^\circ)+i\sin(1^\circ)$. The angle $1^\circ$ equals $\pi/180$, so
\[
z^{360}=e^{360i\pi/180}=e^{2\pi i}=1.
\]
Consequently, $z$ is algebraic over $\mathbb{Q}$ because it satisfies $X^{360}-1=0$. Complex conjugation preserves algebraicity: if $z$ is algebraic, then $\overline z$ is algebraic, since it satisfies the polynomial obtained by conjugating the coefficients of a polynomial satisfied by $z$; here the coefficients are rational. Therefore, using closure of the algebraic numbers under field operations,
\[
\cos(1^\circ)=\frac{z+\overline z}{2}
\]
is algebraic over $\mathbb{Q}$.\end{proof}
